mode=sys.argv[3] if len(sys.argv)>3 else 'idx'
def blocks(m):
    c=m.get('content')
    if isinstance(c,str): return [{'type':'text','text':c}]
    return c or []
with open(P,errors='replace') as f:
    for i,line in enumerate(f,1):
        try: r=json.loads(line)
        except: continue
