        m=r.get('message',{}) or {}
        for b in blocks(m):
            t=b.get('type')
            if t=='text':
                tx=b.get('text','').strip()
                if not tx: continue
                if mode=='idx': tx=tx[:400].replace('\n',' | ')
                print(f"{i} {ts} {r['type']}/TEXT: {tx}")
            elif t=='tool_use':
                nm=b.get('name'); inp=b.get('input',{}) or {}
                if nm=='Agent' or nm=='Task':
                    pr=(inp.get('prompt') or '')[:300].replace('\n',' | ')
                    print(f"{i} {ts} AGENT[{inp.get('model','-')}] desc={inp.get('description','')}: {pr}")
                else:
                    s=json.dumps(inp)[:200].replace('\n',' ')
                    print(f"{i} {ts} TOOL {nm}: {s}")
EOF
