import json,glob,os
rows=[]
for f in sorted(glob.glob('agent-*.jsonl')):
    aid=os.path.basename(f)[:-6]
    meta={}
    mp=aid+'.meta.json'
    if os.path.exists(mp):
        try: meta=json.load(open(mp))
        except: pass
    first=last=None; out=0; ctx=0
    with open(f,errors='replace') as fh:
        for line in fh:
            try: r=json.loads(line)
            except: continue
            ts=r.get('timestamp')
            if ts:
                if first is None or ts<first: first=ts
                if last is None or ts>last: last=ts
            if r.get('type')=='assistant':
                u=(r.get('message') or {}).get('usage') or {}
                out+=u.get('output_tokens',0)
                ctx+=u.get('input_tokens',0)+u.get('cache_creation_input_tokens',0)+u.get('cache_read_input_tokens',0)
    rows.append((first or '',last or '',aid,meta.get('model','-'),meta.get('description','-'),out,ctx))
rows.sort()
for r in rows:
    print(f"{r[0][:19]} .. {r[1][11:19]} {r[2]} model={r[3]} out={r[5]} ctx={r[6]} :: {r[4]}")
EOF
